contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount, address other) public {
        require(other != address(0));

        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherBalBefore = c.balanceOf(other); if (__ESBMC_reverted()) return;
        require(ownerBalBefore >= amount);

        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 ownerBalAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherBalAfter = c.balanceOf(other); if (__ESBMC_reverted()) return;
        assert(!reverted && ownerBalAfter == ownerBalBefore - amount && otherBalAfter == otherBalBefore);
    }
}

